from typing import List

class Solution:
    def maximumPrimeDifference(self, nums: List[int]) -> int:
        def is_prime(x: int) -> bool:
            if x < 2:
                return False
            if x < 4:
                return True
            if x % 2 == 0:
                return False
            i = 3
            while i * i <= x:
                if x % i == 0:
                    return False
                i += 2
            return True

        first = -1
        last = -1
        for i, v in enumerate(nums):
            if is_prime(v):
                if first == -1:
                    first = i
                last = i
        return last - first
