import json
from hypothesis import strategies as st


def _is_prime(x):
    if x < 2:
        return False
    for d in range(2, x):
        if d * d > x:
            break
        if x % d == 0:
            return False
    return True


@st.composite
def gen(draw):
    n = draw(st.integers(1, 8))
    nums = draw(st.lists(st.integers(1, 100), min_size=n, max_size=n))
    # Ensure at least one prime is present; sometimes make all values prime.
    primes = [p for p in range(2, 101) if _is_prime(p)]
    mode = draw(st.integers(0, 3))
    if mode == 0:
        # all primes
        nums = [draw(st.sampled_from(primes)) for _ in range(n)]
    else:
        pos = draw(st.integers(0, n - 1))
        nums[pos] = draw(st.sampled_from(primes))
        if mode == 1:
            # force prime at both ends sometimes
            other = draw(st.integers(0, n - 1))
            nums[other] = draw(st.sampled_from(primes))
    return json.dumps(nums)


def validate(inp):
    try:
        nums = json.loads(inp)
    except Exception:
        return False
    if not isinstance(nums, list):
        return False
    if not (1 <= len(nums) <= 3 * 10 ** 5):
        return False
    if not all(type(x) is int and 1 <= x <= 100 for x in nums):
        return False
    return any(_is_prime(x) for x in nums)


def ref(inp):
    nums = json.loads(inp)
    idx = [i for i, x in enumerate(nums) if _is_prime(x)]
    best = 0
    for i in idx:
        for j in idx:
            best = max(best, abs(i - j))
    return json.dumps(best)
